class Solution {
public:
    long long minimumDifference(vector<int>& nums) {
        int n=nums.size()/3;
        vector<long long> left(3*n),right(3*n+1);
        priority_queue<int> a;long long sum=0;
        for(int i=0;i<2*n;++i) {
            a.push(nums[i]);sum+=nums[i];
            if((int)a.size()>n){sum-=a.top();a.pop();}
            if(i>=n-1) left[i]=sum;
        }
        priority_queue<int,vector<int>,greater<int>> b;sum=0;
        for(int i=3*n-1;i>=n;--i) {
            b.push(nums[i]);sum+=nums[i];
            if((int)b.size()>n){sum-=b.top();b.pop();}
            if(i<=2*n) right[i]=sum;
        }
        long long ans=LLONG_MAX;
        for(int i=n-1;i<2*n;++i) ans=min(ans,left[i]-right[i+1]);
        return ans;
    }
};
